const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB,assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
assert(sh('git rev-parse HEAD')===SHA,'wrong parent SHA');assert(sh(`git hash-object ${TARGET}`)===BLOB,'parent blob drift');const src=fs.readFileSync(TARGET,'utf8'),p=parse(src),expected='31,32,100,124,125,126,127,128,139,140,141,142,143,144,155,179,180';assert(p.declarations.length===76&&p.dead.length===17,`parent drift ${p.declarations.length}/${p.dead.length}`);assert(p.dead.map(d=>d.line).join(',')===expected,'dead line drift');assert(new Set(p.dead.map(d=>d.selector)).size===6,'family drift');const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===9&&p.dead.length-identical===8,'winner drift');let global=0,mobile=0;for(const d of p.dead){if(!d.context)global++;else if(d.context==='@media (max-width: 760px)')mobile++;else throw new Error(`context drift ${d.context}`);assert(d.winnerLine>d.line&&!d.important&&!d.winnerImportant,`cascade drift ${d.line}`)}assert(global===16&&mobile===1,'context counts drift');const nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(`${d.property}:`),`line mismatch ${d.line}`);lines.splice(d.line-1,1)}fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const after=parse(fs.readFileSync(TARGET,'utf8'));assert(after.declarations.length===59&&after.dead.length===0,`candidate drift ${after.declarations.length}/${after.dead.length}`);const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(stat[0]==='0'&&stat[1]==='17'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);const buf=fs.readFileSync(TARGET),hash=crypto.createHash('sha256').update(buf).digest('hex');console.log(`CANDIDATE BUILD PASS|decl=76->59|dead=17->0|families=6|identical=9|changed=8|contexts=global16,mobile760=1|additions=0|deletions=17|hash=${hash}|bytes=${buf.length}`);
